factoriopedia_simulation.init:
game.simulation.camera_zoom = 1.2    game.simulation.camera_position = {0, 0}
game.surfaces[1].build_checkerboard{{-40, -40}, {40, 40}}

enemy = game.surfaces[1].create_entity{name = "small-strafer-pentapod", position = {0, 0}}

step_0 = function()
  if enemy.valid then
      game.simulation.camera_position = {enemy.position.x, enemy.position.y - 0.5}
  end

  script.on_nth_tick(1, function()
      step_0()
  end)
end

